65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
74	     * owner's id, customer code, registration date and membership level, so the create side-effect
75	     * can be audited independently of the application log.
76	     */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    /**
88	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
89	     * and a domain containing at least one dot, with no whitespace in any segment.
90	     */
91	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
92	
93	    /**
94	     * Required national-number length per E.164 country code. A normalized telephone whose country
95	     * code appears here must carry exactly this many national digits after the code; Australia
96	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
97	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
98	     */
99	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
100	
101	    /**
102	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
103	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
104	     */
105	    private static final int MAX_OWNERS_PER_CITY = 50;
106	
107	    /**
108	     * Maximum number of owners that may be registered on a single day (by registration date). A create
109	     * attempted once this many owners already carry today's registration date is rejected with a
110	     * 429 Too Many Requests.
111	     */
112	    private static final int MAX_OWNERS_PER_DAY = 100;
113	
114	    /**
115	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
116	     * owners already carry the new owner's registration date, the created owner is flagged
117	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
118	     */
119	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
120	
121	    /**
122	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
123	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
124	     */
125	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
126	        "ST", "STREET",
127	        "RD", "ROAD",
128	        "AVE", "AVENUE");
129	
130	    /**
131	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
132	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
133	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
134	     * 4-digit postcode.
135	     */
136	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
137	        "NSW", new int[] {2000, 2099},
138	        "VIC", new int[] {3000, 3099},
139	        "QLD", new int[] {4000, 4099});
140	
141	    public OwnerRestControllerV1(ClinicService clinicService,
142	                                 OwnerMapper ownerMapper,
143	                                 PetMapper petMapper,
144	                                 VisitMapper visitMapper) {
145	        this.clinicService = clinicService;
146	        this.ownerMapper = ownerMapper;
147	        this.petMapper = petMapper;
148	        this.visitMapper = visitMapper;
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
154	        Collection<Owner> owners;
155	        if (lastName != null) {
156	            owners = this.clinicService.findOwnerByLastName(lastName);
157	        } else {
158	            owners = this.clinicService.findAllOwners();
159	        }
160	        if (owners.isEmpty()) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
179	        validateRequiredFields(ownerFieldsDto);
180	        HttpHeaders headers = new HttpHeaders();
181	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
182	        rejectFutureRegistrationDate(owner.getRegistrationDate());
183	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
184	        owner.setRegistrationDate(registrationDate);
185	        requireDailyCapacity(registrationDate);
186	        requireCityHasCapacity(owner.getCity());
187	        validatePostcode(owner);
188	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
189	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
190	            joinHousehold(owner);
191	        }
192	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
193	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
194	        requireUniqueIdentity(owner);
195	        owner.setCustomerCode(owner.buildCustomerCode());
196	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
198	        this.clinicService.saveOwner(owner);
199	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
200	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
201	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    /**
208	     * Rejects a create whose supplied registration date is later than the server's current date. A
209	     * registration may be back-dated but never post-dated, so a future date is treated as a client
210	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
211	     * server date.
212	     *
213	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
214	     *     client omitted it
215	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
216	     */
217	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
218	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
219	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
220	        }
221	    }
222	
223	    /**
224	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
225	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
226	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
227	     * existed prior to this create.
228	     *
229	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
230	     *     a business day
231	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
232	     *     registered on that business day
233	     */
234	    private void requireDailyCapacity(LocalDate registrationDate) {
235	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
236	            throw new DailyOwnerLimitException(registrationDate);
237	        }
238	    }
239	
240	    /**
241	     * Counts the existing owners whose registration date equals the given business-day date. This is
242	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
243	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
244	     * the bulk-signup warning.
245	     *
246	     * @param registrationDate the effective business-day registration date to count against
247	     * @return the number of pre-existing owners registered on that date
248	     */
249	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
250	        return this.clinicService.findAllOwners().stream()
251	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
252	            .count();
253	    }
254	
255	    /**
256	     * Rejects an owner whose city already contains the maximum allowed number of owners
257	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
258	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
259	     * create.
260	     *
261	     * @param city the city of the owner being created
262	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
263	     */
264	    private void requireCityHasCapacity(String city) {
265	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
266	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
267	            .count();
268	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
269	            throw new CityOwnerLimitException(city);
270	        }
271	    }
272	
273	    /**
274	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
275	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
276	     * schema) that must fall within the inclusive range permitted for the region derived from the
277	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
278	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
279	     *
280	     * @param owner the owner being created, with its city and postcode set
281	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
282	     */
283	    private void validatePostcode(Owner owner) {
284	        String postcode = owner.getPostcode();
285	        if (postcode == null) {
286	            return;
287	        }
288	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
289	        if (range == null) {
290	            return;
291	        }
292	        int value = Integer.parseInt(postcode);
293	        if (value < range[0] || value > range[1]) {
294	            throw new InvalidOwnerFieldsException(List.of("postcode"));
295	        }
296	    }
297	
298	    /**
299	     * Counts the existing owners that already share the given first name and last name, compared
300	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
301	     * owners that existed prior to this create.
302	     *
303	     * @param firstName the first name of the owner being created
304	     * @param lastName the last name of the owner being created
305	     * @return the number of pre-existing namesakes
306	     */
307	    private int countNamesakes(String firstName, String lastName) {
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
310	                && equalsIgnoreCase(existing.getLastName(), lastName))
311	            .count();
312	    }
313	
314	    /**
315	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
316	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
317	     *
318	     * @param a the first value, possibly {@code null}
319	     * @param b the second value, possibly {@code null}
320	     * @return whether the values are equal ignoring case
321	     */
322	    private boolean equalsIgnoreCase(String a, String b) {
323	        return a == null ? b == null : a.equalsIgnoreCase(b);
324	    }
325	
326	    /**
327	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
328	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
329	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
330	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
331	     *
332	     * @param ownerFieldsDto the submitted owner fields
333	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
334	     */
335	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
336	        List<String> invalidFields = new ArrayList<>();
337	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
338	            invalidFields.add("firstName");
339	        }
340	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
341	            invalidFields.add("lastName");
342	        }
343	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
344	            invalidFields.add("address");
345	        }
346	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
347	            invalidFields.add("city");
348	        }
349	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
350	            invalidFields.add("telephone");
351	        }
352	        if (!invalidFields.isEmpty()) {
353	            throw new InvalidOwnerFieldsException(invalidFields);
354	        }
355	    }
356	
357	    /**
358	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
359	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
360	     * what gets stored and returned.
361	     *
362	     * @param telephone the raw telephone value from the request
363	     * @return the normalized E.164 telephone number
364	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
365	     */
366	    private String normalizeTelephone(String telephone) {
367	        String e164 = toE164(telephone);
368	        if (e164 == null) {
369	            throw new InvalidOwnerFieldsException(List.of("telephone"));
370	        }
371	        return e164;
372	    }
373	
374	    /**
375	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
376	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
377	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
378	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
379	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
380	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
381	     *
382	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
383	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
384	     *
385	     * @param telephone the raw telephone value, possibly {@code null}
386	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
387	     */
388	    private String toE164(String telephone) {
389	        if (telephone == null) {
390	            return null;
391	        }
392	        String cleaned = telephone.replaceAll("[ \\-()]", "");
393	        String digits;
394	        if (cleaned.startsWith("+")) {
395	            digits = cleaned.substring(1);
396	        } else {
397	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
398	            digits = "61" + national;
399	        }
400	        if (!digits.matches("[0-9]{8,15}")) {
401	            return null;
402	        }
403	        if (!nationalNumberLengthValid(digits)) {
404	            return null;
405	        }
406	        return "+" + digits;
407	    }
408	
409	    /**
410	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
411	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
412	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
413	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
414	     * accepted, leaving only the generic total-length rule to apply.
415	     *
416	     * @param digits the E.164 digits without the leading {@code '+'}
417	     * @return {@code true} if the national-number length matches the country code's requirement
418	     */
419	    private boolean nationalNumberLengthValid(String digits) {
420	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
421	            String code = entry.getKey();
422	            if (digits.startsWith(code)) {
423	                return digits.length() - code.length() == entry.getValue();
424	            }
425	        }
426	        return true;
427	    }
428	
429	    /**
430	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
431	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
432	     * and returned lower-cased.
433	     *
434	     * @param email the raw email value from the request, possibly {@code null}
435	     * @return the lower-cased email, or {@code null} when none was supplied
436	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
437	     */
438	    private String normalizeEmail(String email) {
439	        if (!StringUtils.hasText(email)) {
440	            return null;
441	        }
442	        String trimmed = email.trim();
443	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
444	            throw new InvalidOwnerFieldsException(List.of("email"));
445	        }
446	        return trimmed.toLowerCase(Locale.ROOT);
447	    }
448	
449	    /**
450	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
451	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
452	     * owner's normalized telephone, email (empty when absent) and household id joined with
453	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
454	     * owner's. Because the telephone is part of the key, two members of the same household
455	     * (same {@code householdId}) with different telephones have different identity keys and are both
456	     * allowed.
457	     *
458	     * @param owner the owner being created, with its normalized telephone, email and household id set
459	     * @throws DuplicateIdentityException if another owner already has this identity key
460	     */
461	    private void requireUniqueIdentity(Owner owner) {
462	        String identityKey = owner.getIdentityKey();
463	        boolean inUse = this.clinicService.findAllOwners().stream()
464	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
465	        if (inUse) {
466	            throw new DuplicateIdentityException(identityKey);
467	        }
468	    }
469	
470	    /**
471	     * Returns the existing owners that belong to the same household as the given last name and
472	     * address, i.e. those whose last name and address match case-insensitively and with runs of
473	     * whitespace collapsed to a single space.
474	     *
475	     * @param lastName the last name to match
476	     * @param address the address to match
477	     * @return the matching owners (possibly empty, never {@code null})
478	     */
479	    private List<Owner> findHouseholdMembers(String lastName, String address) {
480	        String normalizedLastName = normalizeForHousehold(lastName);
481	        String normalizedAddress = normalizeAddress(address);
482	        return this.clinicService.findAllOwners().stream()
483	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
484	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
485	            .toList();
486	    }
487	
488	    /**
489	     * Joins the owner being created to the shared household of any existing owner(s) that have the
490	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
491	     * member of the household - the existing owners and the new one - is assigned the same stable
492	     * {@code householdId}, so the shared identifier can be read back from any of them.
493	     *
494	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
495	     * the owner is left without a {@code householdId}.
496	     *
497	     * <p>Every member of the household - the existing owners and the new one - is also stamped with
498	     * the household's member count after this create ({@code householdSize}), so the shared size can
499	     * be read back from any of them.
500	     *
501	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
502	     */
503	    private void joinHousehold(Owner owner) {
504	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
505	        if (members.isEmpty()) {
506	            return;
507	        }
508	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
509	        int householdSize = members.size() + 1;
510	        owner.setHouseholdId(householdId);
511	        owner.setHouseholdSize(householdSize);
512	        for (Owner member : members) {
513	            member.setHouseholdId(householdId);
514	            member.setHouseholdSize(householdSize);
515	            this.clinicService.saveOwner(member);
516	        }
517	    }
518	
519	    /**
520	     * Computes the stable, shared household identifier for a last name and address. The value is
521	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
522	     * name and address, so every owner in the same household computes the same identifier.
523	     *
524	     * @param lastName the last name of the household
525	     * @param address the address of the household
526	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
527	     */
528	    private String computeHouseholdId(String lastName, String address) {
529	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
530	        try {
531	            byte[] digest = MessageDigest.getInstance("SHA-256")
532	                .digest(key.getBytes(StandardCharsets.UTF_8));
533	            StringBuilder hex = new StringBuilder();
534	            for (int i = 0; i < 6; i++) {
535	                hex.append(String.format("%02X", digest[i]));
536	            }
537	            return "HH-" + hex;
538	        } catch (NoSuchAlgorithmException e) {
539	            throw new IllegalStateException("SHA-256 algorithm not available", e);
540	        }
541	    }
542	
543	    /**
544	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
545	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
546	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
547	     *
548	     * @param value the raw value, possibly {@code null}
549	     * @return the normalized value
550	     */
551	    private String normalizeForHousehold(String value) {
552	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
553	    }
554	
555	    /**
556	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
557	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
558	     * value yields an empty string.
559	     *
560	     * @param value the raw value, possibly {@code null}
561	     * @return the trimmed, whitespace-collapsed value
562	     */
563	    private String collapseWhitespace(String value) {
564	        if (value == null) {
565	            return "";
566	        }
567	        return value.trim().replaceAll("\\s+", " ");
568	    }
569	
570	    /**
571	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
572	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
573	     * is upper-cased, and common street-type abbreviations are expanded as whole words
574	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
575	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
576	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
577	     *
578	     * @param address the raw address value, possibly {@code null}
579	     * @return the normalized address
580	     */
581	    private String normalizeAddress(String address) {
582	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
583	        if (collapsed.isEmpty()) {
584	            return "";
585	        }
586	        String[] tokens = collapsed.split(" ");
587	        StringBuilder normalized = new StringBuilder();
588	        for (int i = 0; i < tokens.length; i++) {
589	            if (i > 0) {
590	                normalized.append(' ');
591	            }
592	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
593	        }
594	        return normalized.toString();
595	    }
596	
597	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
598	    @Override
599	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
600	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
601	        if (currentOwner == null) {
602	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
603	        }
604	        currentOwner.setAddress(ownerFieldsDto.getAddress());
605	        currentOwner.setCity(ownerFieldsDto.getCity());
606	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
607	        currentOwner.setLastName(ownerFieldsDto.getLastName());
608	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
609	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
610	        this.clinicService.saveOwner(currentOwner);
611	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
612	    }
613	
614	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
615	    @Transactional
616	    @Override
617	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
618	        Owner owner = this.clinicService.findOwnerById(ownerId);
619	        if (owner == null) {
620	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
621	        }
622	        this.clinicService.deleteOwner(owner);
623	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
624	    }
625	
626	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
627	    @Override
628	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
629	        Owner owner = this.clinicService.findOwnerById(ownerId);
630	        if (owner == null) {
631	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
632	        }
633	        HttpHeaders headers = new HttpHeaders();
634	        Pet pet = petMapper.toPet(petFieldsDto);
635	        owner.setId(ownerId);
636	        pet.setOwner(owner);
637	        pet.getType().setName(null);
638	        this.clinicService.savePet(pet);
639	        PetDto petDto = petMapper.toPetDto(pet);
640	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
641	            .buildAndExpand(pet.getId()).toUri());
642	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
643	    }
644	
645	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
646	    @Override
647	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
648	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
649	        if (currentOwner != null) {
650	            Pet currentPet = this.clinicService.findPetById(petId);
651	            if (currentPet != null) {
652	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
653	                currentPet.setName(petFieldsDto.getName());
654	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
655	                this.clinicService.savePet(currentPet);
656	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
657	            }
658	        }
659	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
660	    }
661	
662	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
663	    @Override
664	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
665	        HttpHeaders headers = new HttpHeaders();
666	        Visit visit = visitMapper.toVisit(visitFieldsDto);
667	        Pet pet = new Pet();
668	        pet.setId(petId);
669	        visit.setPet(pet);
670	        this.clinicService.saveVisit(visit);
671	        VisitDto visitDto = visitMapper.toVisitDto(visit);
672	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
673	            .buildAndExpand(visit.getId()).toUri());
674	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
675	    }
676	
677	
678	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
679	    @Override
680	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
681	        Owner owner = this.clinicService.findOwnerById(ownerId);
682	        if (owner != null) {
683	            Pet pet = owner.getPet(petId);
684	            if (pet != null) {
685	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
686	            }
687	        }
688	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
689	    }
690	}
