31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    private String email;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date", columnDefinition = "DATE")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "household_size")
74	    private Integer householdSize;
75	
76	    @Column(name = "postcode")
77	    private String postcode;
78	
79	    @Column(name = "bulk_signup_warning")
80	    private Boolean bulkSignupWarning;
81	
82	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
83	    private Set<Pet> pets;
84	
85	    /**
86	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
87	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
88	     */
89	    private static final Map<String, String> CITY_REGION = Map.of(
90	        "Sydney", "NSW",
91	        "Melbourne", "VIC",
92	        "Brisbane", "QLD");
93	
94	    /**
95	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
96	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
97	     */
98	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
99	        "NSW", new int[] {2000, 2099},
100	        "VIC", new int[] {3000, 3099},
101	        "QLD", new int[] {4000, 4099});
102	
103	    public String getAddress() {
104	        return this.address;
105	    }
106	
107	    public void setAddress(String address) {
108	        this.address = address;
109	    }
110	
111	    public String getCity() {
112	        return this.city;
113	    }
114	
115	    public void setCity(String city) {
116	        this.city = city;
117	    }
118	
119	    public String getTelephone() {
120	        return this.telephone;
121	    }
122	
123	    public void setTelephone(String telephone) {
124	        this.telephone = telephone;
125	    }
126	
127	    public String getEmail() {
128	        return this.email;
129	    }
130	
131	    public void setEmail(String email) {
132	        this.email = email;
133	    }
134	
135	    public LocalDate getRegistrationDate() {
136	        return this.registrationDate;
137	    }
138	
139	    public void setRegistrationDate(LocalDate registrationDate) {
140	        this.registrationDate = registrationDate;
141	    }
142	
143	    public LocalDate getBirthDate() {
144	        return this.birthDate;
145	    }
146	
147	    public void setBirthDate(LocalDate birthDate) {
148	        this.birthDate = birthDate;
149	    }
150	
151	    /**
152	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
153	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
154	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
155	     * elapsed from the birth date to the registration date (defaulting to the server's current date
156	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
157	     *
158	     * @return the age band, or {@code null} when the birth date is absent
159	     */
160	    public String getAgeBand() {
161	        if (this.birthDate == null) {
162	            return null;
163	        }
164	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
165	        int years = Period.between(this.birthDate, asAt).getYears();
166	        if (years < 18) {
167	            return "MINOR";
168	        }
169	        if (years < 65) {
170	            return "ADULT";
171	        }
172	        return "SENIOR";
173	    }
174	
175	    public String getCustomerCode() {
176	        return this.customerCode;
177	    }
178	
179	    public void setCustomerCode(String customerCode) {
180	        this.customerCode = customerCode;
181	    }
182	
183	    /**
184	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
185	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
186	     * from the owner's own customer code and registration date; {@code null} when either is absent.
187	     *
188	     * @return the membership number, or {@code null} when it cannot be derived
189	     */
190	    public String getMembershipNumber() {
191	        if (this.customerCode == null || this.registrationDate == null) {
192	            return null;
193	        }
194	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
195	    }
196	
197	    /**
198	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
199	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
200	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
201	     *
202	     * @return the Luhn check digit, or {@code null} when the customer code is absent
203	     */
204	    public Integer getCheckDigit() {
205	        if (this.customerCode == null) {
206	            return null;
207	        }
208	        int sum = 0;
209	        boolean dbl = true;
210	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
211	            char c = this.customerCode.charAt(i);
212	            if (c < '0' || c > '9') {
213	                continue;
214	            }
215	            int d = c - '0';
216	            if (dbl) {
217	                d *= 2;
218	                if (d > 9) {
219	                    d -= 9;
220	                }
221	            }
222	            sum += d;
223	            dbl = !dbl;
224	        }
225	        return (10 - (sum % 10)) % 10;
226	    }
227	
228	    /**
229	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
230	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
231	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
232	     *
233	     * @return the membership level, an integer from 1 to 3
234	     */
235	    public Integer getMembershipLevel() {
236	        int level = 1;
237	        boolean hasEmail = this.email != null && !this.email.isBlank();
238	        if (hasEmail) {
239	            level++;
240	        }
241	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
242	        if (hasNoNamesakes) {
243	            level++;
244	        }
245	        return Math.min(level, 3);
246	    }
247	
248	    /**
249	     * The owner's locality, the canonical region string. Once the owner has a
250	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
251	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
252	     * source of truth. Before the customer code is assigned (for example while a create is still
253	     * validating the postcode) it falls back to the region the code will be built from: the
254	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
255	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
256	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
257	     *
258	     * @return the canonical region string, or {@code 'UNKNOWN'}
259	     */
260	    public String getLocality() {
261	        if (this.customerCode != null) {
262	            int dash = this.customerCode.indexOf('-');
263	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
264	        }
265	        return deriveRegion();
266	    }
267	
268	    /**
269	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
270	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
271	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
272	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
273	     * the same region for known cities but disambiguates cities that share a name.
274	     *
275	     * @return the canonical region string, or {@code 'UNKNOWN'}
276	     */
277	    private String deriveRegion() {
278	        String region = regionFromPostcode();
279	        if (region != null) {
280	            return region;
281	        }
282	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
283	    }
284	
285	    /**
286	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
287	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
288	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
289	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
290	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
291	     * owner's region, telephone and last name. Call this once at create time and store the result via
292	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
293	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
294	     *
295	     * @return the assembled customer code
296	     */
297	    public String buildCustomerCode() {
298	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
299	    }
300	
301	    /**
302	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
303	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
304	     *
305	     * @param value the value to hash
306	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
307	     */
308	    private static String sha256Hex8(String value) {
309	        try {
310	            byte[] digest = MessageDigest.getInstance("SHA-256")
311	                .digest(value.getBytes(StandardCharsets.UTF_8));
312	            StringBuilder hex = new StringBuilder(8);
313	            for (int i = 0; i < 4; i++) {
314	                hex.append(String.format("%02X", digest[i]));
315	            }
316	            return hex.toString();
317	        }
318	        catch (NoSuchAlgorithmException e) {
319	            throw new IllegalStateException("SHA-256 algorithm not available", e);
320	        }
321	    }
322	
323	    /**
324	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
325	     * absent, not a 4-digit number, or in no known range.
326	     *
327	     * @return the matching region, or {@code null}
328	     */
329	    private String regionFromPostcode() {
330	        if (this.postcode == null) {
331	            return null;
332	        }
333	        int value;
334	        try {
335	            value = Integer.parseInt(this.postcode.trim());
336	        }
337	        catch (NumberFormatException ex) {
338	            return null;
339	        }
340	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
341	            int[] range = entry.getValue();
342	            if (value >= range[0] && value <= range[1]) {
343	                return entry.getKey();
344	            }
345	        }
346	        return null;
347	    }
348	
349	    /**
350	     * The owner's preferred contact channel, derived from the owner's details. Returns
351	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
352	     *
353	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
354	     */
355	    public String getContactPreference() {
356	        boolean hasEmail = this.email != null && !this.email.isBlank();
357	        return hasEmail ? "EMAIL" : "PHONE";
358	    }
359	
360	    /**
361	     * The owner's identity key, the single derived value used for duplicate detection. It is the
362	     * owner's normalized telephone, email (empty when absent) and household id joined with
363	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
364	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
365	     * are equal, so two members of the same household with different telephones differ here and are
366	     * both allowed.
367	     *
368	     * @return the derived identity key
369	     */
370	    public String getIdentityKey() {
371	        return (this.telephone == null ? "" : this.telephone) + "|"
372	            + (this.email == null ? "" : this.email) + "|"
373	            + (this.householdId == null ? "" : this.householdId);
374	    }
375	
376	    public String getHouseholdId() {
377	        return this.householdId;
378	    }
379	
380	    public void setHouseholdId(String householdId) {
381	        this.householdId = householdId;
382	    }
383	
384	    public Integer getNamesakeCount() {
385	        return this.namesakeCount;
386	    }
387	
388	    public void setNamesakeCount(Integer namesakeCount) {
389	        this.namesakeCount = namesakeCount;
390	    }
391	
392	    public Integer getHouseholdSize() {
393	        return this.householdSize;
394	    }
395	
396	    public void setHouseholdSize(Integer householdSize) {
397	        this.householdSize = householdSize;
398	    }
399	
400	    public String getPostcode() {
401	        return this.postcode;
402	    }
403	
404	    public void setPostcode(String postcode) {
405	        this.postcode = postcode;
406	    }
407	
408	    public Boolean getBulkSignupWarning() {
409	        return this.bulkSignupWarning;
410	    }
411	
412	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
413	        this.bulkSignupWarning = bulkSignupWarning;
414	    }
415	
416	    /**
417	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
418	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
419	     */
420	    @PrePersist
421	    void onCreate() {
422	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
423	    }
424	
425	    /**
426	     * Resolves the effective registration date and rolls it onto a business day. An absent
427	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
428	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
429	     * becomes the following Monday, while any weekday is returned unchanged.
430	     *
431	     * <p>This is the single definition of both the defaulting and the business-day roll, used
432	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
433	     * stamps the owner and by the create endpoint that counts owners per business day.
434	     *
435	     * @param supplied the registration date from the request, or {@code null} when none was supplied
436	     * @return the effective registration date, guaranteed to fall on a business day
437	     */
438	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
439	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
440	        return switch (effective.getDayOfWeek()) {
441	            case SATURDAY -> effective.plusDays(2);
442	            case SUNDAY -> effective.plusDays(1);
443	            default -> effective;
444	        };
445	    }
446	
447	    protected Set<Pet> getPetsInternal() {
448	        if (this.pets == null) {
449	            this.pets = new HashSet<>();
450	        }
451	        return this.pets;
452	    }
453	
454	    protected void setPetsInternal(Set<Pet> pets) {
455	        this.pets = pets;
456	    }
457	
458	    public List<Pet> getPets() {
459	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
460	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
461	        return Collections.unmodifiableList(sortedPets);
462	    }
463	
464	    public void setPets(List<Pet> pets) {
465	        this.pets = new HashSet<>(pets);
466	    }
467	
468	    public void addPet(Pet pet) {
469	        getPetsInternal().add(pet);
470	        pet.setOwner(this);
471	    }
472	
473	    /**
474	     * Return the Pet with the given name, or null if none found for this Owner.
475	     *
476	     * @param name to test
477	     * @return true if pet name is already in use
478	     */
479	    public Pet getPet(String name) {
480	        return getPet(name, false);
481	    }
482	
483	    /**
484	     * Return the Pet with the given name, or null if none found for this Owner.
485	     *
486	     * @param name to test
487	     * @return true if pet name is already in use
488	     */
489	    public Pet getPet(String name, boolean ignoreNew) {
490	        name = name.toLowerCase();
491	        for (Pet pet : getPetsInternal()) {
492	            if (!ignoreNew || !pet.isNew()) {
493	                String compName = pet.getName();
494	                compName = compName.toLowerCase();
495	                if (compName.equals(name)) {
496	                    return pet;
497	                }
498	            }
499	        }
500	        return null;
501	    }
502	
503	    public Pet getPet(Integer petId) {
504	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
505	    }
506	
507	    @Override
508	    public String toString() {
509	        return new ToStringCreator(this)
510	
511	            .append("id", this.getId())
512	            .append("new", this.isNew())
513	            .append("lastName", this.getLastName())
514	            .append("firstName", this.getFirstName())
515	            .append("address", this.address)
516	            .append("city", this.city)
517	            .append("telephone", this.telephone)
518	            .toString();
519	    }
520	}
